import 'package:dio/dio.dart';import 'package:flutter/widgets.dart';import 'api_password.dart';import '../Local/local_storage_keys.dart';import '../Local/local_storage_service.dart';import 'api_endpoints.dart';class DioHelper {  static late Dio dio;  static void init() {    dio = Dio(      BaseOptions(        baseUrl: ApiEndpoints.baseUrl,        receiveDataWhenStatusError: true,        connectTimeout: const Duration(seconds: 10),        receiveTimeout: const Duration(seconds: 10),        headers: {          'Content-Type': 'application/json',          'Accept': 'application/json',        },        queryParameters: {          'api_password': ApiPassword.password,        },      ),    );    // Add logging interceptor in debug mode    dio.interceptors.add(      LogInterceptor(        request: true,        requestHeader: true,        requestBody: true,        responseHeader: true,        responseBody: true,        error: true,      ),    );  }  /// Handles GET requests and extracts API messages  static Future<Response?> getData({    required String path,    Map<String, dynamic>? queryParameters,  }) async {    try {      final response = await dio.get(        path,        queryParameters: queryParameters,        options: await _getAuthorizationHeader(),      );      // Return the successful response      return response;    } on DioException catch (e) {      debugPrint('❌ GET Error: ${e.message}');      // Extract and display API message if available      String apiMessage = _getApiMessage(e.response?.data);      if (apiMessage.isNotEmpty) {        debugPrint('📄 API Message: $apiMessage');      }      // Return the error response so we can access its data      return e.response;    } catch (e) {      debugPrint('❌ General Error: $e');      return Response(        requestOptions: RequestOptions(path: path),        statusCode: 500,        statusMessage: e.toString(),      );    }  }  /// Handles POST requests and extracts API messages  static Future<Response?> postData({    required String path,    required dynamic data,    Map<String, dynamic>? queryParameters,  }) async {    try {      final response = await dio.post(        path,        data: data,        queryParameters: queryParameters,        options: await _getAuthorizationHeader(),      );      // Return the successful response      return response;    } on DioException catch (e) {      debugPrint('❌ POST Error: ${e.message}');      // Extract and display API message if available      String apiMessage = _getApiMessage(e.response?.data);      if (apiMessage.isNotEmpty) {        debugPrint('📄 API Message: $apiMessage');      }      // Return the error response so we can access its data      return e.response;    } catch (e) {      debugPrint('❌ General Error: $e');      return Response(        requestOptions: RequestOptions(path: path),        statusCode: 500,        statusMessage: e.toString(),      );    }  }  /// Handles PUT requests and extracts API messages  static Future<Response?> putData({    required String path,    required dynamic data,    Map<String, dynamic>? queryParameters,  }) async {    try {      final response = await dio.put(        path,        data: data,        queryParameters: queryParameters,        options: await _getAuthorizationHeader(),      );      // Return the successful response      return response;    } on DioException catch (e) {      debugPrint('❌ PUT Error: ${e.message}');      // Extract and display API message if available      String apiMessage = _getApiMessage(e.response?.data);      if (apiMessage.isNotEmpty) {        debugPrint('📄 API Message: $apiMessage');      }      // Return the error response so we can access its data      return e.response;    } catch (e) {      debugPrint('❌ General Error: $e');      return Response(        requestOptions: RequestOptions(path: path),        statusCode: 500,        statusMessage: e.toString(),      );    }  }  /// Handles DELETE requests and extracts API messages  static Future<Response?> deleteData({    required String path,    dynamic data,    Map<String, dynamic>? queryParameters,  }) async {    try {      final response = await dio.delete(        path,        data: data,        queryParameters: queryParameters,        options: await _getAuthorizationHeader(),      );      // Return the successful response      return response;    } on DioException catch (e) {      debugPrint('❌ DELETE Error: ${e.message}');      // Extract and display API message if available      String apiMessage = _getApiMessage(e.response?.data);      if (apiMessage.isNotEmpty) {        debugPrint('📄 API Message: $apiMessage');      }      // Return the error response so we can access its data      return e.response;    } catch (e) {      debugPrint('❌ General Error: $e');      return Response(        requestOptions: RequestOptions(path: path),        statusCode: 500,        statusMessage: e.toString(),      );    }  }  /// Helper to extract API message from response data  static String _getApiMessage(dynamic data) {    if (data == null) return '';    if (data is Map<String, dynamic>) {      // Try to get message from different common fields      if (data.containsKey('message') && data['message'] is String) {        return data['message'];      }      if (data.containsKey('error') && data['error'] is String) {        return data['error'];      }      // Handle nested error objects      if (data.containsKey('errors')) {        var errors = data['errors'];        if (errors is Map && errors.isNotEmpty) {          var firstError = errors.values.first;          if (firstError is List && firstError.isNotEmpty) {            return firstError.first.toString();          }          return firstError.toString();        } else if (errors is List && errors.isNotEmpty) {          return errors.first.toString();        }      }    } else if (data is String) {      return data;    }    return '';  }  static Future<Options> _getAuthorizationHeader() async {    String? token = LocalStorageService.getValue(LocalStorageKeys.token);    return Options(      headers: {        'Authorization': token != null && token.isNotEmpty ? 'Bearer $token' : '',      },    );  }}